import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { MapContainer, TileLayer, GeoJSON } from 'react-leaflet';
import L from 'leaflet';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import Navbar from './Navbar';
import bdDistrictsData from '../data/bd-districts.json';
import 'leaflet/dist/leaflet.css';

// Fix for default marker icons in react-leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png'
});

const StatsPage = () => {
  const [stats, setStats] = useState([]);
  const [totalPosts, setTotalPosts] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Bangladesh center coordinates for map centering
  const mapCenter = [23.6850, 90.3563];

  useEffect(() => {
    fetchHeatmapStats();
  }, []);

  const fetchHeatmapStats = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');

      if (!token) {
        setError('Please login to view statistics');
        return;
      }

      const response = await axios.get(
        'http://localhost:5000/api/posts/stats/heatmap',
        {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        }
      );

      if (response.data.success) {
        console.log('📊 Heatmap data received:', response.data.data);
        setStats(response.data.data);
        const total = response.data.data.reduce((sum, stat) => sum + stat.crimeCount, 0);
        setTotalPosts(total);
        setError('');
      }
    } catch (err) {
      console.error('Error fetching heatmap stats:', err);
      setError(err.response?.data?.message || 'Failed to fetch statistics');
    } finally {
      setLoading(false);
    }
  };

  // Get top 5 crime areas for chart
  const topAreas = stats.slice(0, 5);

  // Get color based on crime density (choropleth color scheme)
  const getColor = (density) => {
    if (density > 50) return '#8B0000'; // Dark red for very high crime
    if (density > 20) return '#FF6B6B'; // Red for high crime
    if (density > 10) return '#FFA500'; // Orange for medium crime
    if (density > 0) return '#FFD700'; // Yellow for low crime
    return '#90EE90'; // Light green for no crime
  };

  // Style function for GeoJSON features (choropleth style)
  const styleFeature = (feature) => {
    // Find matching crime data for this district
    const districtName = feature.properties.name;
    const crimeData = stats.find(s => s.district === districtName);
    const crimeCount = crimeData?.crimeCount || 0;

    return {
      fillColor: getColor(crimeCount),
      weight: 2,
      opacity: 1,
      color: '#333',
      dashArray: '3',
      fillOpacity: 0.7
    };
  };

  // Function to add hover tooltips and popups
  const onEachFeature = (feature, layer) => {
    const districtName = feature.properties.name;
    const crimeData = stats.find(s => s.district === districtName);
    const crimeCount = crimeData?.crimeCount || 0;
    const verifications = crimeData?.totalVerifications || 0;
    const refutations = crimeData?.totalRefutations || 0;

    // Create popup content
    const popupContent = `
      <div class="p-3">
        <p class="font-bold text-gray-900 text-lg">📍 ${districtName}</p>
        <p class="text-sm text-red-600 font-semibold mt-2">${crimeCount} incident${crimeCount !== 1 ? 's' : ''}</p>
        <p class="text-xs text-gray-600 mt-1">✓ ${verifications} verified</p>
        <p class="text-xs text-gray-600">✗ ${refutations} refuted</p>
      </div>
    `;

    // Bind popup to layer
    layer.bindPopup(popupContent);

    // Show popup on hover
    layer.on('mouseover', function () {
      this.openPopup();
    });

    layer.on('mouseout', function () {
      this.closePopup();
    });
  };

  // Determine color based on crime count (for legend display)
  const getCircleColor = (count) => {
    if (count > 10) return '#dc2626'; // Red for high crime
    if (count < 5) return '#eab308'; // Yellow for low crime
    return '#f97316'; // Orange for medium crime
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50 to-gray-100">
        <Navbar />
        <div className="flex items-center justify-center py-20">
          <div className="text-center">
            <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-blue-600 mx-auto"></div>
            <p className="mt-6 text-gray-600 text-lg font-medium">Loading crime statistics...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50 to-gray-100">
      <Navbar />
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Header Section */}
        <div className="mb-8">
          <div className="bg-gradient-to-r from-red-600 to-red-800 rounded-2xl shadow-2xl overflow-hidden p-8 text-white">
            <h1 className="text-4xl font-bold mb-2">Crime Statistics & Heatmap</h1>
            <p className="text-red-100 text-lg">Real-time crime density analysis across Bangladesh</p>
            <p className="text-red-100 text-sm mt-3">📊 Total Incident Reports: <span className="font-bold text-xl">{totalPosts}</span></p>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 border-2 border-red-200 text-red-800 px-6 py-4 rounded-xl mb-6 flex items-start gap-3">
            <svg className="w-6 h-6 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4v.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <div>
              <p className="font-semibold">Error</p>
              <p className="text-sm">{error}</p>
            </div>
          </div>
        )}

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
          {/* Total Crimes Card */}
          <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold mb-2">Total Crimes</p>
                <p className="text-3xl font-bold text-gray-900">{totalPosts}</p>
              </div>
              <div className="w-14 h-14 bg-red-100 rounded-full flex items-center justify-center">
                <svg className="w-8 h-8 text-red-600" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm0-13c-2.76 0-5 2.24-5 5s2.24 5 5 5 5-2.24 5-5-2.24-5-5-5z" />
                </svg>
              </div>
            </div>
          </div>

          {/* Highest Crime Area Card */}
          <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold mb-2">Highest Crime District</p>
                {stats.length > 0 ? (
                  <>
                    <p className="text-lg font-bold text-gray-900">{stats[0].district}</p>
                    <p className="text-sm text-red-600 font-semibold mt-1">{stats[0].crimeCount} crimes</p>
                  </>
                ) : (
                  <p className="text-gray-500 text-sm">No data</p>
                )}
              </div>
              <div className="w-14 h-14 bg-orange-100 rounded-full flex items-center justify-center">
                <svg className="w-8 h-8 text-orange-600" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2L2 7v10c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V7l-10-5z" />
                </svg>
              </div>
            </div>
          </div>

          {/* Areas with Crime Card */}
          <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold mb-2">Districts Affected</p>
                <p className="text-3xl font-bold text-gray-900">{stats.filter(s => s.crimeCount > 0).length}</p>
              </div>
              <div className="w-14 h-14 bg-blue-100 rounded-full flex items-center justify-center">
                <svg className="w-8 h-8 text-blue-600" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5 7.67 11 8.5 11zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z" />
                </svg>
              </div>
            </div>
          </div>

          {/* Avg Crimes Per Area Card */}
          <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-600 text-sm font-semibold mb-2">Avg per Area</p>
                <p className="text-3xl font-bold text-gray-900">
                  {(() => {
                    const affectedAreas = stats.filter(s => s.crimeCount > 0);
                    return affectedAreas.length > 0 ? (totalPosts / affectedAreas.length).toFixed(1) : 0;
                  })()}
                </p>
              </div>
              <div className="w-14 h-14 bg-green-100 rounded-full flex items-center justify-center">
                <svg className="w-8 h-8 text-green-600" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z" />
                </svg>
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Bar Chart Section */}
          <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
            <h2 className="text-2xl font-bold text-gray-900 mb-6 flex items-center gap-2">
              <svg className="w-6 h-6 text-blue-600" fill="currentColor" viewBox="0 0 24 24">
                <path d="M5 9.2h3V19H5zM10.6 5h2.8v14h-2.8zm5.6 8H19v6h-2.8z" />
              </svg>
              Crime Count by District
            </h2>
            {topAreas.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={topAreas}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="district" angle={-45} textAnchor="end" height={80} interval={0} />
                  <YAxis />
                  <Tooltip
                    content={({ active, payload }) => {
                      if (active && payload && payload[0]) {
                        return (
                          <div className="bg-white p-3 rounded-lg shadow-lg border border-gray-200">
                            <p className="font-semibold text-gray-900">{payload[0].payload.area}</p>
                            <p className="text-red-600 font-bold">{payload[0].value} crimes</p>
                          </div>
                        );
                      }
                      return null;
                    }}
                  />
                  <Bar dataKey="crimeCount" fill="#dc2626" name="Crime Count" radius={[8, 8, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-80 flex items-center justify-center">
                <p className="text-gray-500">No data available</p>
              </div>
            )}
          </div>

          {/* Crime Density Legend & Info */}
          <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
            <h2 className="text-2xl font-bold text-gray-900 mb-6 flex items-center gap-2">
              <svg className="w-6 h-6 text-orange-600" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm0-13c-2.76 0-5 2.24-5 5s2.24 5 5 5 5-2.24 5-5-2.24-5-5-5z" />
              </svg>
              Crime Density Legend
            </h2>

            <div className="space-y-4">
              {/* Very High Risk */}
              <div className="p-4 rounded-lg bg-red-50 border-2 border-red-200">
                <div className="flex items-center gap-3 mb-2">
                  <div className="w-6 h-6 rounded" style={{ backgroundColor: '#8B0000' }}></div>
                  <span className="font-bold text-gray-900">Very High Risk</span>
                </div>
                <p className="text-sm text-gray-700 ml-9">More than 50 crimes</p>
              </div>

              {/* High Risk */}
              <div className="p-4 rounded-lg bg-red-50 border-2 border-red-200">
                <div className="flex items-center gap-3 mb-2">
                  <div className="w-6 h-6 rounded" style={{ backgroundColor: '#FF6B6B' }}></div>
                  <span className="font-bold text-gray-900">High Risk</span>
                </div>
                <p className="text-sm text-gray-700 ml-9">20-50 crimes</p>
              </div>

              {/* Medium Risk */}
              <div className="p-4 rounded-lg bg-orange-50 border-2 border-orange-200">
                <div className="flex items-center gap-3 mb-2">
                  <div className="w-6 h-6 rounded" style={{ backgroundColor: '#FFA500' }}></div>
                  <span className="font-bold text-gray-900">Medium Risk</span>
                </div>
                <p className="text-sm text-gray-700 ml-9">10-20 crimes</p>
              </div>

              {/* Low Risk */}
              <div className="p-4 rounded-lg bg-yellow-50 border-2 border-yellow-200">
                <div className="flex items-center gap-3 mb-2">
                  <div className="w-6 h-6 rounded" style={{ backgroundColor: '#FFD700' }}></div>
                  <span className="font-bold text-gray-900">Low Risk</span>
                </div>
                <p className="text-sm text-gray-700 ml-9">1-10 crimes</p>
              </div>

              {/* No Crime */}
              <div className="p-4 rounded-lg bg-green-50 border-2 border-green-200">
                <div className="flex items-center gap-3 mb-2">
                  <div className="w-6 h-6 rounded" style={{ backgroundColor: '#90EE90' }}></div>
                  <span className="font-bold text-gray-900">No Crime</span>
                </div>
                <p className="text-sm text-gray-700 ml-9">No reported incidents</p>
              </div>

              {/* All Districts List */}
              <div className="mt-6 pt-6 border-t border-gray-200">
                <h3 className="font-bold text-gray-900 mb-4">All Districts</h3>
                <div className="space-y-2 max-h-48 overflow-y-auto">
                  {stats.map((district, index) => (
                    <div key={index} className="flex items-center justify-between p-2 hover:bg-gray-50 rounded">
                      <div className="flex items-center gap-2">
                        <div
                          className="w-3 h-3 rounded-full"
                          style={{ backgroundColor: getCircleColor(district.crimeCount) }}
                        ></div>
                        <span className="text-sm font-semibold text-gray-700">{district.district}</span>
                      </div>
                      <span className="text-sm font-bold text-gray-900">{district.crimeCount}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Map Section */}
        <div className="mt-8 bg-white rounded-2xl shadow-lg overflow-hidden border border-gray-100">
          <div className="p-6 bg-gradient-to-r from-blue-50 to-gray-50 border-b border-gray-200">
            <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              <svg className="w-6 h-6 text-blue-600" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm1-13h-2v6h6v-2h-4z" />
              </svg>
              Crime Density Choropleth Map
            </h2>
            <p className="text-gray-600 text-sm mt-2">Districts are colored based on crime density - darker colors indicate higher crime rates</p>
          </div>

          <div style={{ position: 'relative', width: '100%', height: '500px' }}>
            <MapContainer 
              center={mapCenter} 
              zoom={6} 
              style={{ 
                height: '100%', 
                width: '100%',
                position: 'absolute',
                top: 0,
                left: 0
              }}
              className="rounded-b-2xl"
            >
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution='&copy; OpenStreetMap contributors'
              />
              {/* Choropleth Map: Color districts based on crime density */}
              <GeoJSON 
                data={bdDistrictsData}
                style={styleFeature}
                onEachFeature={onEachFeature}
              />
            </MapContainer>
          </div>
        </div>

        {/* Insights Section */}
        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          {/* Most Verified Card */}
          <div className="bg-green-50 rounded-2xl shadow-lg p-6 border-2 border-green-200">
            <h3 className="text-lg font-bold text-green-900 mb-4 flex items-center gap-2">
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z" />
              </svg>
              Most Verified Areas
            </h3>
            <div className="space-y-2">
              {stats
                .sort((a, b) => b.totalVerifications - a.totalVerifications)
                .slice(0, 3)
                .map((district, index) => (
                  <div key={index} className="flex items-center justify-between p-2 bg-white rounded-lg">
                    <span className="text-sm font-semibold text-gray-700">{district.district}</span>
                    <span className="text-sm font-bold text-green-600">{district.totalVerifications}</span>
                  </div>
                ))}
            </div>
          </div>

          {/* Most Refuted Card */}
          <div className="bg-red-50 rounded-2xl shadow-lg p-6 border-2 border-red-200">
            <h3 className="text-lg font-bold text-red-900 mb-4 flex items-center gap-2">
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                <path d="M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z" />
              </svg>
              Most Refuted Areas
            </h3>
            <div className="space-y-2">
              {stats
                .sort((a, b) => b.totalRefutations - a.totalRefutations)
                .slice(0, 3)
                .map((district, index) => (
                  <div key={index} className="flex items-center justify-between p-2 bg-white rounded-lg">
                    <span className="text-sm font-semibold text-gray-700">{district.district}</span>
                    <span className="text-sm font-bold text-red-600">{district.totalRefutations}</span>
                  </div>
                ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StatsPage;
